#nullable enable // autogenerated

using MVZ2.GameContent.Projectiles;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Projectiles;
using MVZ2Logic.Entities;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Tools.Unity;
using UnityEngine;

namespace MVZ2.GameContent.Contraptions
{
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.cattailMKII_Evoke)]
    public class CattailMKII_Evoke : ContraptionEvokeBehaviour
    {
        public CattailMKII_Evoke(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Evoke(Entity entity)
        {
            base.Evoke(entity);

            for (int i = 0; i < PROJECTILE_COUNT; i++)
            {
                var angle = i * PROJECTILE_ANGLE;
                var direction = Vector2.right.RotateClockwise(angle) * HORIZONTAL_SPEED;
                var xSpeed = direction.x;
                var ySpeed = Y_SPEED;
                var zSpeed = direction.y;

                var shootArgs = entity.GetShootParams();
                shootArgs.spawnParam.EntityVelocity = new Vector3(xSpeed, ySpeed, zSpeed);
                shootArgs.position = entity.GetCenter();
                shootArgs.projectileID = VanillaProjectileID.meowmereProjectile;
                shootArgs.damage = entity.GetDamage() * DAMAGE_MULTIPLIER;
                shootArgs.velocity = new Vector3(xSpeed, ySpeed, zSpeed);

                entity.ShootProjectile(shootArgs);
            }

            entity.PlaySound(VanillaSoundID.meowmere, volume: 0.5f);
        }
        public const int PROJECTILE_COUNT = 9;
        public const float PROJECTILE_ANGLE = 360f / PROJECTILE_COUNT;
        public const float Y_SPEED = 10f;
        public const float HORIZONTAL_SPEED = 20f;
        public const float DAMAGE_MULTIPLIER = 4f;
    }
}